+        MARKER_PREFIX: MARKER_PREFIX,
+        MARKER_SUFFIX: MARKER_SUFFIX,
+        VERDICTS: VERDICTS,
+        LABEL_APPROVED: LABEL_APPROVED,
+        LABEL_REWORK: LABEL_REWORK,
