    var removeFromIssue = loser === LABEL_REWORK ? !!st.issueHasRework : false;
    if (!removeFromPr && !removeFromIssue) return null;
    return {
        loserLabel: loser,
        removeFromPr: removeFromPr,
        removeFromIssue: removeFromIssue,
        effective: effective,
