        lines.push('- ' + older.verdict + ' at ' + (older.at || 'unknown time') + ' (source: ' + older.source + ')');
        lines.push('- ' + newer.verdict + ' at ' + (newer.at || 'unknown time') + ' (source: ' + newer.source + ')');
        lines.push('');
        lines.push('Newest wins: **' + newer.verdict + '** — removing `' + loserLabel + '`' +
