        var OTHER = 'ffffffffeeeeeeeeddddddddcccccccc77777777';
        var otherRecords = rvC.parseVerdictRecords([
            marker(OTHER, 'BLOCK', '2026-10-09T05:47:30.000Z'),
            marker(OTHER, 'APPROVE', '2026-10-09T05:47:40.000Z')
